mapper.sql:
AND ( FALSE
OR a.teacher_user_id = #{q.userId}
OR EXISTS ( SELECT 1 FROM organization_user_mappings rm JOIN organization_user_mappings tm ON tm.organization_code = rm.organization_code WHERE rm.user_id = #{q.userId} AND tm.user_id = a.teacher_user_id AND rm.status = 'ACTIVE' AND tm.status = 'ACTIVE' AND rm.effective_start_date <= CURRENT_DATE AND tm.effective_start_date <= CURRENT_DATE AND (rm.effective_end_date IS NULL OR rm.effective_end_date >= CURRENT_DATE) AND (tm.effective_end_date IS NULL OR tm.effective_end_date >= CURRENT_DATE) )
OR EXISTS ( SELECT 1 FROM evaluation_organization_mappings pm WHERE pm.user_id = #{q.userId} AND pm.organization_code = a.organization_code AND pm.business_type = 'FACULTY_ACHIEVEMENT' AND pm.data_scope IN ('DEPARTMENT', 'COLLEGE', 'BUSINESS', 'ALL') )
)

WHERE a.achievement_type = 'FR-032' AND a.deleted_yn = 'N'

AND a.management_no = #{q.managementNo}
AND u.login_id ILIKE CONCAT('%', #{q.teacherName}, '%')
AND a.management_item_code = #{q.managementItemCode}
AND a.achievement_status = #{q.certificationStatus}
AND a.evaluation_year = #{q.evaluationYear}
AND a.organization_code = #{q.organizationCode}

mapper.select:
SELECT FROM education_achievements a JOIN users u ON u.user_id = a.teacher_user_id
ORDER BY a.achievement_date DESC, a.achievement_id DESC
LIMIT #{q.pageSize} OFFSET #{q.pageOffset}

mapper.insert:
INSERT INTO education_achievements (
    achievement_type, management_no, teacher_user_id, organization_code, evaluation_year,
    management_item_code, achievement_date, achievement_name, achievement_detail, attachment_ref,
    created_by, updated_by, request_id
)
VALUES (
    'FR-032', #{managementNo}, #{teacherUserId}, #{organizationCode}, #{evaluationYear},
    #{managementItemCode}, #{achievementDate}, #{achievementName}, #{achievementDetail}, #{attachmentRef},
    #{actorId}, #{actorId}, #{requestId}
)

INSERT INTO data_change_histories (
    target_business, target_key, change_type, field_name, before_value, after_value,
    changed_by, change_reason, request_id
)
VALUES (
    'education_achievements', CAST(#{id} AS text), #{action}, 'FR-032', #{before}, #{after},
    #{userId}, '취업률 실적 저장', #{requestId}
)
